     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→
    18→const CORS_HEADERS = {
    19→  "Access-Control-Allow-Origin": "*",
    20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    21→  "Access-Control-Allow-Headers": "Content-Type",
    22→  "Content-Type": "application/json",
    23→};
    24→
    25→async function handleZipCheck(shop: string | null, zip: string | null) {
    26→  if (!shop || !zip) {
    27→    return new Response(
    28→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    29→      { status: 400, headers: CORS_HEADERS },
    30→    );
    31→  }
    32→
    33→  const normalizedZip = zip.trim().toUpperCase();
    34→
    35→  const zipRecord = await db.zipCode.findUnique({
    36→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
    37→  });
    38→
    39→  // Fetch widget config for custom messages (falls back to defaults)
    40→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
    41→
    42→  if (!zipRecord || !zipRecord.isActive) {
    43→    // Check if zip exists but is inactive — treat as not found
    44→    const notFoundMsg =
    45→      widgetConfig?.notFoundMessage ??
    46→      "This zip code was not found in our system.";
    47→
    48→    if (!zipRecord) {
    49→      return new Response(
    50→        JSON.stringify({
    51→          allowed: false,
    52→          message: notFoundMsg,
    53→          notFound: true,
    54→        }),
    55→        { status: 200, headers: CORS_HEADERS },
    56→      );
    57→    }
    58→
    59→    // Inactive zip — treat same as not found
    60→    return new Response(
    61→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
    62→      { status: 200, headers: CORS_HEADERS },
    63→    );
    64→  }
    65→
    66→  if (zipRecord.type === "blocked") {
    67→    const errorMsg =
    68→      zipRecord.message ??
    69→      widgetConfig?.errorMessage ??
    70→      "Sorry, we don't deliver to this area yet.";
    71→
    72→    return new Response(
    73→      JSON.stringify({ allowed: false, message: errorMsg }),
    74→      { status: 200, headers: CORS_HEADERS },
    75→    );
    76→  }
    77→
    78→  // Allowed
    79→  const successMsg =
    80→    zipRecord.message ??
    81→    widgetConfig?.successMessage ??
    82→    "Great news! We deliver to your area.";
    83→
    84→  return new Response(
    85→    JSON.stringify({
    86→      allowed: true,
    87→      message: successMsg,
    88→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
    89→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
    90→      showWaitlist: false,
    91→    }),
    92→    { status: 200, headers: CORS_HEADERS },
    93→  );
    94→}
    95→
    96→// Handle GET requests: ?shop=...&zip=...
    97→export const loader = async ({ request }: LoaderFunctionArgs) => {
    98→  const url = new URL(request.url);
    99→
   100→  // Handle CORS preflight
   101→  if (request.method === "OPTIONS") {
   102→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   103→  }
   104→
   105→  const shop = url.searchParams.get("shop");
   106→  const zip = url.searchParams.get("zip");
   107→  return handleZipCheck(shop, zip);
   108→};
   109→
   110→// Handle POST requests with JSON body: { shop, zip }
   111→export const action = async ({ request }: ActionFunctionArgs) => {
   112→  if (request.method === "OPTIONS") {
   113→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   114→  }
   115→
   116→  let shop: string | null = null;
   117→  let zip: string | null = null;
   118→
   119→  try {
   120→    const body = await request.json();
   121→    shop = body?.shop ?? null;
   122→    zip = body?.zip ?? null;
   123→  } catch {
   124→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   125→      status: 400,
   126→      headers: CORS_HEADERS,
   127→    });
   128→  }
   129→
   130→  return handleZipCheck(shop, zip);
   131→};
   132→

